    counts = {}
    for action in actions:
        try:
            action()
        except Exception as e:
            if isinstance(e, LookupError):
                key = "lookup"
            elif isinstance(e, ArithmeticError):
                key = "arithmetic"
            else:
                key = "other"
            counts[key] = counts.get(key, 0) + 1
    return counts

def common_parent(a, b):
    for c in a.__mro__:
        if c in b.__mro__:
            return c.__name__

