def level_counts(lines):
    counts = {}
    for n, line in enumerate(lines, start=1):
        if ": " not in line:
            logging.warning("Skipping line %s", n)
            continue
        level = line.split(": ", 1)[0]
        counts[level] = counts.get(level, 0) + 1
    return counts

