        raise RowError(f"Expected 3 fields, got {len(fields)}")
    return fields

def parse_row(line):
    name, age, city = split_fields(line)
    if not name:
        raise RowError("Missing name")
    try:
        age = int(age)
    except ValueError as e:
        raise RowError(f"Bad age: {age}") from e
    return {"name": name, "age": age, "city": city}

def import_rows(lines, strict=False):
    rows = []
    problems = []
    for number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            rows.append(parse_row(line))
        except RowError as e:
            message = f"Line {number}: {e}"
            if strict:
                raise RowError(message) from e
            logging.warning(message)
            problems.append(message)
    return rows, problems

def import_text(text, strict=False):
    lines = text.splitlines()
    report = []
    try:
        if not lines or lines[0].strip() != "name,age,city":
            raise RowError(f"Unexpected header: {lines[0] if lines else ''}")
        rows, problems = import_rows(lines[1:], strict=strict)
    except RowError as e:
        report.append(f"Import stopped: {e}")
    else:
        report.append(f"Imported {len(rows)} rows")
        report.append(f"Skipped {len(problems)} rows")
        report.extend(problems)
    finally:
        logging.info("Import finished")
    return report

